export interface ConnectorConfig {
  /** Brevo API key for authentication */
  brevoApiKey: string;
  /** Brevo list ID to subscribe the contact to */
  listId: number;
  /** Typeform field ID for the email question */
  emailFieldId: string;
  /** Typeform field ID for the name question */
  nameFieldId: string;
  /** Optional: Brevo attribute name for first name (default: 'FNAME') */
  firstNameAttribute?: string;
  /** Optional: Brevo attribute name for last name (default: 'LNAME') */
  lastNameAttribute?: string;
  /** Optional: Enable update if contact exists (default: false) */
  updateEnabled?: boolean;
  /** Injected fetch for testing */
  fetch?: typeof fetch;
}

export interface TypeformWebhookPayload {
  event_id: string;
  event_type: string;
  form_response: {
    form_id: string;
    token: string;
    submitted_at: string;
    answers: Array<{
      type: string;
      email?: string;
      text?: string;
      field: {
        id: string;
        type: string;
      };
    }>;
  };
}

export interface HandleResult {
  contactId: number;
  email: string;
  listId: number;
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch;
}

function extractAnswer(
  answers: TypeformWebhookPayload['form_response']['answers'],
  fieldId: string
): { email?: string; text?: string } | undefined {
  return answers.find((a) => a.field.id === fieldId);
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required config
  if (!config.brevoApiKey) throw new Error('Missing required config: brevoApiKey');
  if (!config.listId) throw new Error('Missing required config: listId');
  if (!config.emailFieldId) throw new Error('Missing required config: emailFieldId');
  if (!config.nameFieldId) throw new Error('Missing required config: nameFieldId');

  // Validate payload structure
  if (!payload.form_response?.answers?.length) {
    throw new Error('Invalid payload: missing form_response.answers');
  }

  // Extract email
  const emailAnswer = extractAnswer(payload.form_response.answers, config.emailFieldId);
  if (!emailAnswer?.email) {
    throw new Error(`Email not found for field ID: ${config.emailFieldId}`);
  }
  const email = emailAnswer.email;

  // Extract name
  const nameAnswer = extractAnswer(payload.form_response.answers, config.nameFieldId);
  if (!nameAnswer?.text) {
    throw new Error(`Name not found for field ID: ${config.nameFieldId}`);
  }
  const fullName = nameAnswer.text.trim();

  // Split name into first/last (simple split on first space)
  const nameParts = fullName.split(/\s+/);
  const firstName = nameParts[0] ?? '';
  const lastName = nameParts.slice(1).join(' ') || undefined;

  // Build Brevo request body
  const attributes: Record<string, string> = {};
  const firstNameAttr = config.firstNameAttribute ?? 'FNAME';
  const lastNameAttr = config.lastNameAttribute ?? 'LNAME';
  if (firstName) attributes[firstNameAttr] = firstName;
  if (lastName) attributes[lastNameAttr] = lastName;

  const body = {
    email,
    attributes,
    listIds: [config.listId],
    updateEnabled: config.updateEnabled ?? false,
  };

  // Call Brevo API
  const fetchFn = getFetch(config);
  const response = await fetchFn('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': config.brevoApiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    throw new Error(
      `Brevo API error: ${response.status} ${response.statusText} at POST https://api.brevo.com/v3/contacts - ${errorText}`
    );
  }

  const result = (await response.json()) as { id: number };
  return {
    contactId: result.id,
    email,
    listId: config.listId,
  };
}

