    event_id: 'evt-1',
    event_type: 'form_response',
    form_response: {
      form_id: 'form-1',
      token: 'token-1',
      submitted_at: '2024-01-01T00:00:00Z',
      answers: [
        {
          type: 'email',
          email: 'test@example.com',
          field: { id: 'email-field-id', type: 'email' },
        },
        {
          type: 'text',
          text: 'John Doe',
          field: { id: 'name-field-id', type: 'short_text' },
        },
      ],
    },
  };

  it('happy path: creates contact and subscribes to list', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST');
      expect(req.url).toBe('https://api.brevo.com/v3/contacts');
      expect(req.headers.get('api-key')).toBe('test-api-key');
      expect(req.json).toEqual({
        email: 'test@example.com',
        attributes: { FNAME: 'John', LNAME: 'Doe' },
        listIds: [456],
        updateEnabled: false,
      });
      return jsonResponse({ id: 789 }, 201);
    });

    const result = await handle(basePayload, { ...baseConfig, fetch });
    expect(result).toEqual({ contactId: 789, email: 'test@example.com', listId: 456 });
    expect(calls).toHaveLength(1);
  });

  it('uses custom attribute names when provided', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({
        email: 'test@example.com',
        attributes: { FIRST_NAME: 'John', LAST_NAME: 'Doe' },
        listIds: [456],
        updateEnabled: false,
      });
      return jsonResponse({ id: 789 }, 201);
    });

    const config: ConnectorConfig = {
      ...baseConfig,
      firstNameAttribute: 'FIRST_NAME',
      lastNameAttribute: 'LAST_NAME',
      fetch,
    };
    await handle(basePayload, config);
    expect(calls).toHaveLength(1);
  });

  it('handles single name (no last name)', async () => {
    const payload: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'email-field-id', type: 'email' } },
          { type: 'text', text: 'Cher', field: { id: 'name-field-id', type: 'short_text' } },
        ],
      },
    };

    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({
        email: 'test@example.com',
        attributes: { FNAME: 'Cher' },
        listIds: [456],
        updateEnabled: false,
      });
      return jsonResponse({ id: 789 }, 201);
    });

    await handle(payload, { ...baseConfig, fetch });
    expect(calls).toHaveLength(1);
  });

  it('throws when email field is missing', async () => {
    const payload: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: [{ type: 'text', text: 'John', field: { id: 'name-field-id', type: 'short_text' } }],
      },
    };

    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Email not found for field ID: email-field-id'
    );
  });

  it('throws when name field is missing', async () => {
    const payload: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: [{ type: 'email', email: 'test@example.com', field: { id: 'email-field-id', type: 'email' } }],
      },
    };

    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Name not found for field ID: name-field-id'
    );
  });

  it('throws when config brevoApiKey is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(basePayload, { ...baseConfig, brevoApiKey: '', fetch })).rejects.toThrow(
      'Missing required config: brevoApiKey'
    );
  });

  it('throws when config listId is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(basePayload, { ...baseConfig, listId: 0, fetch })).rejects.toThrow(
      'Missing required config: listId'
    );
  });

  it('throws on non-2xx response from Brevo', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Brevo API error: 401 Unauthorized at POST https://api.brevo.com/v3/contacts'
