        attributes: { FNAME: 'John', LNAME: 'Doe' },
        listIds: [456],
        updateEnabled: true,
      });
      return jsonResponse({ id: 789 }, 201);
    });

    await handle(basePayload, { ...baseConfig, updateEnabled: true, fetch });
    expect(calls).toHaveLength(1);
  });

  it('throws when payload answers array is missing', async () => {
    const payload = {
      ...basePayload,
      form_response: { ...basePayload.form_response, answers: undefined as any },
    };
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Invalid payload: missing form_response.answers'
    );
  });
});

